data.res_body:
{
  "type": "object",
  "required": [
    "code",
    "msg",
    "succ",
    "data"
  ],
  "properties": {
    "code": {
      "type": "string",
      "description": "业务状态码，成功为 0，非 0 表示业务失败。"
    },
    "msg": {
      "type": "string",
      "description": "业务提示文案，前端优先展示该字段。"
    },
    "message": {
      "type": "string",
      "description": "兼容字段，通常为空或不返回。"
    },
    "succ": {
      "type": "boolean",
      "description": "请求是否成功，成功为 true，失败为 false。"
    },
    "data": {
      "type": "object",
      "description": "活动详情数据，包含展示配置、参与资格、任务、奖励和当前用户进度。",
      "required": [
        "visible",
        "serverTime",
        "alreadyJoined",
        "participantEligible",
        "subActivityViews",
        "taskViews"
      ],
      "properties": {
        "visible": {
          "type": "boolean",
          "description": "活动是否可在用户侧展示；未发布、已下线、展示期外时为 false。"
        },
        "serverTime": {
          "type": "number",
          "description": "服务端当前时间，毫秒时间戳，用于倒计时和校准客户端时间。"
        },
        "campaignId": {
          "type": "string",
          "description": "活动业务 ID，前端后续报名、刷新进度、排行榜等接口继续传该值。"
        },
        "campaignName": {
          "type": "string",
          "description": "后台活动名称，主要用于排查和兜底展示。"
        },
        "title": {
          "type": "string",
          "description": "当前语言下活动标题。"
        },
        "subtitle": {
          "type": "string",
          "description": "当前语言下活动副标题。"
        },
        "ruleTitle": {
          "type": "string",
          "description": "当前语言下规则区标题。"
        },
        "ruleContent": {
          "type": "string",
          "description": "当前语言下活动规则内容，渲染格式按运营配置约定。"
        },
        "webBannerUrl": {
          "type": "string",
          "description": "Web 端活动 banner 图片地址。"
        },
        "appBannerUrl": {
          "type": "string",
          "description": "App 端活动 banner 图片地址。"
        },
        "startTime": {
          "type": "number",
          "description": "活动可参与开始时间，毫秒时间戳。"
        },
        "endTime": {
          "type": "number",
          "description": "活动可参与结束时间，毫秒时间戳。"
        },
        "displayStartTime": {
          "type": "number",
          "description": "活动开始展示时间，毫秒时间戳。"
        },
        "displayEndTime": {
          "type": "number",
          "description": "活动结束展示时间，毫秒时间戳。"
        },
        "alreadyJoined": {
          "type": "boolean",
          "description": "当前登录用户是否已报名；未登录时为 false。"
        },
        "rejectReason": {
          "type": "string",
          "description": "当前用户不能报名或不能参与的原因；可参与时为 NONE。"
        },
        "participantConfigType": {
          "type": "string",
          "description": "活动参与对象配置类型；ALL=全量用户，NEW_USER=新用户，OLD_USER=老用户，LIMITED_TAG=限定用户标签，LIMITED_USER_TYPE=限定用户类型，KYC=KYC 用户，REGION_EXCLUDE=禁用地区用户。"
        },
        "participantEligible": {
          "type": "boolean",
          "description": "当前用户是否命中参与对象配置。"
        },
        "joinButtonStatus": {
          "type": "string",
          "description": "报名按钮状态；HIDDEN=隐藏，CAN_JOIN=可报名，JOINED=已报名，LOGIN_REQUIRED=需要登录，BLOCKED=不可报名。"
        },
        "subActivityViews": {
          "type": "array",
          "description": "子活动分组视图，用于按模块渲染任务。",
          "items": {
            "type": "object",
            "properties": {
              "subActivityId": {
                "type": "string",
                "description": "子活动业务 ID。"
              },
              "subActivityName": {
                "type": "string",
                "description": "当前语言下子活动名称。"
              },
              "subActivityTitle": {
                "type": "string",
                "description": "当前语言下子活动副标题或说明。"
              },
              "sortNo": {
                "type": "number",
                "description": "子活动展示顺序，值越小越靠前。"
              },
              "taskViews": {
                "type": "array",
                "description": "当前子活动下的任务视图列表。",
                "items": {
                  "type": "object",
                  "properties": {
                    "taskGroupId": {
                      "type": "string",
                      "description": "任务组业务 ID。"
                    },
                    "taskGroupName": {
                      "type": "string",
                      "description": "当前语言下的任务组名称。"
                    },
                    "taskMode": {
                      "type": "string",
                      "description": "任务玩法类型；SINGLE=单一任务，COMBINE=组合任务，LADDER=阶梯任务，ADVANCED=进阶任务，RANKING=排行榜任务。注意：具体业务任务类型看 conditionDefinitions[].conditionType。"
                    },
                    "logicType": {
                      "type": "string",
                      "description": "组合任务的条件关系；AND 表示全部条件完成，OR 表示任一条件完成。非组合任务可为空。"
                    },
                    "triggerType": {
                      "type": "string",
                      "description": "奖励触发方式；CLAIM=用户手动领取，AUTO_ON_COMPLETE=达标自动发放，MANUAL=线下人工发放。"
                    },
                    "sortNo": {
                      "type": "number",
                      "description": "任务展示顺序，值越小越靠前。"
                    },
                    "progressResult": {
                      "type": "object",
                      "description": "当前登录用户在该任务组下的进度结果，字段来自 GrowthActivityProgressResult。活动可见且有任务时返回对象；未报名或 RANKING 排行榜任务返回空进度对象（conditionProgresses=[]，taskModeResult.completed=false），不是活动级总进度。",
                      "properties": {
                        "conditionProgresses": {
                          "type": "array",
                          "description": "条件维度真实进度列表，字段来自 ConditionProgress。每条记录通过 taskConditionId 与 conditionDefinitions[].taskConditionId 关联，用于展示单个原子条件当前进度。",
                          "items": {
                            "type": "object",
                            "properties": {
                              "taskConditionId": {
                                "type": "string",
                                "description": "条件配置 ID，对应 growth_task_condition.id；与 conditionDefinitions[].taskConditionId 一一关联。"
                              },
                              "completed": {
                                "type": "boolean",
                                "description": "当前条件是否已经完成，由对应 ActivityConditionHandler 计算得到。"
                              },
                              "currentValue": {
                                "type": "number",
                                "description": "当前进度值，BigDecimal 数值；例如当前交易量、充值额，布尔类条件通常用 0/1。"
                              },
                              "targetValue": {
                                "type": "number",
                                "description": "目标门槛值，BigDecimal 数值；例如目标交易量、充值额，布尔类条件通常为 1。"
                              }
                            },
                            "required": [
                              "taskConditionId",
                              "completed",
                              "currentValue",
                              "targetValue"
                            ]
                          }
                        },
                        "taskModeResult": {
                          "type": "object",
                          "properties": {
                            "completed": {
                              "type": "boolean",
                              "description": "当前任务组是否达到可领奖或可发奖条件；按钮状态 buttonStatus 会基于该字段和领取记录继续换算。"
                            },
                            "completedConditionIds": {
                              "type": "array",
                              "description": "SINGLE/COMBINE 任务中已完成的条件 ID 列表；LADDER/ADVANCED 通常为空数组。",
                              "items": {
                                "type": "string"
                              }
                            },
                            "completedTierIds": {
                              "type": "array",
                              "description": "档位任务已完成档位 ID 列表：LADDER 只放最高已完成档位，ADVANCED 放所有已完成档位；非档位任务为空数组。",
                              "items": {
                                "type": "number"
                              }
                            },
                            "selectedTierId": {
                              "type": "number",
                              "description": "LADDER 阶梯任务当前锁定的最高达标档位 ID；SINGLE/COMBINE/ADVANCED 通常为 null。"
                            }
                          },
                          "description": "任务玩法聚合结果，字段来自 TaskModeResult。由 SINGLE/COMBINE/LADDER/ADVANCED 等 TaskModeProcessor 基于 conditionProgresses 和档位配置计算。",
                          "required": [
                            "completed",
                            "completedConditionIds",
                            "completedTierIds",
                            "selectedTierId"
                          ]
                        }
                      },
                      "required": [
                        "conditionProgresses",
                        "taskModeResult"
                      ]
                    },
                    "conditionDefinitions": {
                      "type": "array",
                      "description": "任务条件定义列表；前端用它展示任务要求，并通过 conditionType 判断是 KYC、合约、现货、充值等业务任务。",
                      "items": {
                        "type": "object",
                        "properties": {
                          "taskConditionId": {
                            "type": "string",
                            "description": "条件业务 ID；与进度里的 conditionProgresses[].taskConditionId 对应。"
                          },
                          "tierId": {
                            "type": "number",
                            "description": "所属档位 ID；阶梯任务、进阶任务使用，普通单一/组合任务为空。"
                          },
                          "conditionName": {
                            "type": "string",
                            "description": "当前语言下的条件名称，例如“完成 KYC”“合约交易额”。"
                          },
                          "conditionSubtitle": {
                            "type": "string",
                            "description": "当前语言下的条件副标题或补充说明，例如“活动期累计完成 100 USDT”。"
                          },
                          "conditionType": {
                            "type": "string",
                            "description": "条件业务类型；REGISTER=注册任务，KYC_LEVEL=KYC 认证任务，NET_DEPOSIT_USDT=活动期净充值任务，TOTAL_DEPOSIT_USDT=累计充值任务，SPOT_VOLUME_USDT=现货交易任务，CONTRACT_VOLUME_USDT=合约交易任务，TOTAL_VOLUME_USDT=总交易量任务。"
                          },
                          "operator": {
                            "type": "string",
                            "description": "条件比较方式，例如 GTE=大于等于，LTE=小于等于，EQ=等于，IN=包含。"
                          },
                          "actionType": {
                            "type": "string",
                            "description": "条件未完成时建议前端跳转的页面；GO_REGISTER=注册页，GO_KYC=KYC 认证页，GO_DEPOSIT=充值页，GO_SPOT=现货交易页，GO_CONTRACT=合约交易页。"
                          },
                          "targetValue": {
                            "type": "number",
                            "description": "条件目标值，例如目标交易量、目标充值额；注册、KYC 等非数值条件可为空或按后端配置返回。"
                          },
                          "unit": {
                            "type": "string",
                            "description": "条件目标值和进度值的单位，例如 USDT。"
                          },
                          "sortNo": {
                            "type": "number",
                            "description": "条件展示顺序，值越小越靠前。"
                          },
                          "startTime": {
                            "type": "number",
                            "description": "条件统计开始时间，毫秒时间戳；交易量、充值额等活动期累计条件使用。"
                          },
                          "endTime": {
                            "type": "number",
                            "description": "条件统计结束时间，毫秒时间戳；交易量、充值额等活动期累计条件使用。"
                          }
                        }
                      }
                    },
                    "buttonStatus": {
                      "type": "string",
                      "description": "当前用户在该任务上的按钮状态，例如 IN_PROGRESS=进行中，CAN_CLAIM=可领取，CLAIMED=已领取，AUTO_ISSUE_PENDING=自动发放处理中，OFFLINE_MANUAL=线下发放。"
                    },
                    "rewardIds": {
                      "type": "array",
                      "description": "任务绑定的奖励 ID 列表。",
                      "items": {
                        "type": "string"
                      }
                    },
                    "rewards": {
                      "type": "array",
                      "description": "任务绑定的奖励展示信息列表。",
                      "items": {
                        "type": "object",
                        "properties": {
                          "rewardId": {
                            "type": "string",
                            "description": "奖励配置 ID；用户领取奖励接口使用该值作为路径参数。"
                          },
                          "taskConditionId": {
                            "type": "string",
                            "description": "奖励绑定的条件 ID；单一任务条件级奖励使用。"
                          },
                          "tierId": {
                            "type": "number",
                            "description": "奖励绑定的档位 ID；阶梯任务、进阶任务使用。"
                          },
                          "rankStart": {
                            "type": "number",
                            "description": "排行榜奖励起始名次。"
                          },
                          "rankEnd": {
                            "type": "number",
                            "description": "排行榜奖励结束名次。"
                          },
                          "rewardName": {
                            "type": "string",
                            "description": "当前语言下的奖励名称。"
                          },
                          "rewardType": {
                            "type": "string",
                            "description": "奖励类型；COUPON=卡券，CASH=现金，TRIAL_BONUS=体验金，MANUAL=人工配置奖励。"
                          },
                          "rewardAmount": {
                            "type": "number",
                            "description": "奖励数量或面额。"
                          },
                          "rewardUnit": {
                            "type": "string",
                            "description": "奖励单位，例如 USDT、%。"
                          },
                          "issueMode": {
                            "type": "string",
                            "description": "奖励发放方式；CLAIM=用户手动领取，AUTO_ON_COMPLETE=达标自动发放，MANUAL=线下人工发放。"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "taskViews": {
          "type": "array",
          "description": "扁平任务视图，方便前端不分子活动时直接渲染。",
          "items": {
            "type": "object",
            "properties": {
              "taskGroupId": {
                "type": "string",
                "description": "任务组业务 ID。"
              },
              "taskGroupName": {
                "type": "string",
                "description": "当前语言下的任务组名称。"
              },
              "taskMode": {
                "type": "string",
                "description": "任务玩法类型；SINGLE=单一任务，COMBINE=组合任务，LADDER=阶梯任务，ADVANCED=进阶任务，RANKING=排行榜任务。注意：具体业务任务类型看 conditionDefinitions[].conditionType。"
              },
              "logicType": {
                "type": "string",
                "description": "组合任务的条件关系；AND 表示全部条件完成，OR 表示任一条件完成。非组合任务可为空。"
              },
              "triggerType": {
                "type": "string",
                "description": "奖励触发方式；CLAIM=用户手动领取，AUTO_ON_COMPLETE=达标自动发放，MANUAL=线下人工发放。"
              },
              "sortNo": {
                "type": "number",
                "description": "任务展示顺序，值越小越靠前。"
              },
              "progressResult": {
                "type": "object",
                "description": "当前登录用户在该任务组下的进度结果，字段来自 GrowthActivityProgressResult。活动可见且有任务时返回对象；未报名或 RANKING 排行榜任务返回空进度对象（conditionProgresses=[]，taskModeResult.completed=false），不是活动级总进度。",
                "properties": {
                  "conditionProgresses": {
                    "type": "array",
                    "description": "条件维度真实进度列表，字段来自 ConditionProgress。每条记录通过 taskConditionId 与 conditionDefinitions[].taskConditionId 关联，用于展示单个原子条件当前进度。",
                    "items": {
                      "type": "object",
                      "properties": {
                        "taskConditionId": {
                          "type": "string",
                          "description": "条件配置 ID，对应 growth_task_condition.id；与 conditionDefinitions[].taskConditionId 一一关联。"
                        },
                        "completed": {
                          "type": "boolean",
                          "description": "当前条件是否已经完成，由对应 ActivityConditionHandler 计算得到。"
                        },
                        "currentValue": {
                          "type": "number",
                          "description": "当前进度值，BigDecimal 数值；例如当前交易量、充值额，布尔类条件通常用 0/1。"
                        },
                        "targetValue": {
                          "type": "number",
                          "description": "目标门槛值，BigDecimal 数值；例如目标交易量、充值额，布尔类条件通常为 1。"
                        }
                      },
                      "required": [
                        "taskConditionId",
                        "completed",
                        "currentValue",
                        "targetValue"
                      ]
                    }
                  },
                  "taskModeResult": {
                    "type": "object",
                    "properties": {
                      "completed": {
                        "type": "boolean",
                        "description": "当前任务组是否达到可领奖或可发奖条件；按钮状态 buttonStatus 会基于该字段和领取记录继续换算。"
                      },
                      "completedConditionIds": {
                        "type": "array",
                        "description": "SINGLE/COMBINE 任务中已完成的条件 ID 列表；LADDER/ADVANCED 通常为空数组。",
                        "items": {
                          "type": "string"
                        }
                      },
                      "completedTierIds": {
                        "type": "array",
                        "description": "档位任务已完成档位 ID 列表：LADDER 只放最高已完成档位，ADVANCED 放所有已完成档位；非档位任务为空数组。",
                        "items": {
                          "type": "number"
                        }
                      },
                      "selectedTierId": {
                        "type": "number",
                        "description": "LADDER 阶梯任务当前锁定的最高达标档位 ID；SINGLE/COMBINE/ADVANCED 通常为 null。"
                      }
                    },
                    "description": "任务玩法聚合结果，字段来自 TaskModeResult。由 SINGLE/COMBINE/LADDER/ADVANCED 等 TaskModeProcessor 基于 conditionProgresses 和档位配置计算。",
                    "required": [
                      "completed",
                      "completedConditionIds",
                      "completedTierIds",
                      "selectedTierId"
                    ]
                  }
                },
                "required": [
                  "conditionProgresses",
                  "taskModeResult"
                ]
              },
              "conditionDefinitions": {
                "type": "array",
                "description": "任务条件定义列表；前端用它展示任务要求，并通过 conditionType 判断是 KYC、合约、现货、充值等业务任务。",
                "items": {
                  "type": "object",
                  "properties": {
                    "taskConditionId": {
                      "type": "string",
                      "description": "条件业务 ID；与进度里的 conditionProgresses[].taskConditionId 对应。"
                    },
                    "tierId": {
                      "type": "number",
                      "description": "所属档位 ID；阶梯任务、进阶任务使用，普通单一/组合任务为空。"
                    },
                    "conditionName": {
                      "type": "string",
                      "description": "当前语言下的条件名称，例如“完成 KYC”“合约交易额”。"
                    },
                    "conditionSubtitle": {
                      "type": "string",
                      "description": "当前语言下的条件副标题或补充说明，例如“活动期累计完成 100 USDT”。"
                    },
                    "conditionType": {
                      "type": "string",
                      "description": "条件业务类型；REGISTER=注册任务，KYC_LEVEL=KYC 认证任务，NET_DEPOSIT_USDT=活动期净充值任务，TOTAL_DEPOSIT_USDT=累计充值任务，SPOT_VOLUME_USDT=现货交易任务，CONTRACT_VOLUME_USDT=合约交易任务，TOTAL_VOLUME_USDT=总交易量任务。"
                    },
                    "operator": {
                      "type": "string",
                      "description": "条件比较方式，例如 GTE=大于等于，LTE=小于等于，EQ=等于，IN=包含。"
                    },
                    "actionType": {
                      "type": "string",
                      "description": "条件未完成时建议前端跳转的页面；GO_REGISTER=注册页，GO_KYC=KYC 认证页，GO_DEPOSIT=充值页，GO_SPOT=现货交易页，GO_CONTRACT=合约交易页。"
                    },
                    "targetValue": {
                      "type": "number",
                      "description": "条件目标值，例如目标交易量、目标充值额；注册、KYC 等非数值条件可为空或按后端配置返回。"
                    },
                    "unit": {
                      "type": "string",
                      "description": "条件目标值和进度值的单位，例如 USDT。"
                    },
                    "sortNo": {
                      "type": "number",
                      "description": "条件展示顺序，值越小越靠前。"
                    },
                    "startTime": {
                      "type": "number",
                      "description": "条件统计开始时间，毫秒时间戳；交易量、充值额等活动期累计条件使用。"
                    },
                    "endTime": {
                      "type": "number",
                      "description": "条件统计结束时间，毫秒时间戳；交易量、充值额等活动期累计条件使用。"
                    }
                  }
                }
              },
              "buttonStatus": {
                "type": "string",
                "description": "当前用户在该任务上的按钮状态，例如 IN_PROGRESS=进行中，CAN_CLAIM=可领取，CLAIMED=已领取，AUTO_ISSUE_PENDING=自动发放处理中，OFFLINE_MANUAL=线下发放。"
              },
              "rewardIds": {
                "type": "array",
                "description": "任务绑定的奖励 ID 列表。",
                "items": {
                  "type": "string"
                }
              },
              "rewards": {
                "type": "array",
                "description": "任务绑定的奖励展示信息列表。",
                "items": {
                  "type": "object",
                  "properties": {
                    "rewardId": {
